/**
 * Toast.Card: one toast in the viewport, with its timer, its dismissal and its exit.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/toast.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, DestroyRef, ViewEncapsulation, inject, input } from '@angular/core'

import {
  Icon,
  MEMBER_PROVIDERS,
  Render,
  TOAST_TONE_ICON,
  cell,
  classes,
  composingKey,
  derived,
  elementRef,
  focusAfterToast,
  hostRef,
  isTemplate,
  removeToast,
  setup,
  toast,
  toastClock,
  toastTimeLeft,
  useMember,
  watchEffect,
  type IconProps,
  type ToastRecord,
} from '@polymorph/angular'
import { usePresence } from '@polymorph/angular/motion'
import styles from '@polymorph/recipes/overlays/toast.module.css'
import { Button, type ButtonProps } from '../controls/Button'

/** Toast.Card: one toast in the viewport, with its timer, its dismissal and its exit: the inputs it takes, by the React member's prop names. */
export interface ToastCardProps {
  record: ToastRecord
  /**
   * The close button’s accessible name.
   */
  dismissLabel: string
  /**
   * The reader is on the list, so the timer waits.
   */
  paused: boolean
}

/** Toast.Card: one toast in the viewport, with its timer, its dismissal and its exit. */
@Component({
  selector: 'li[pmToastCard]',
  encapsulation: ViewEncapsulation.None,
  host: {
    '[attr.class]': 'e1()',
    '[style.--radix-toast-swipe-move-x]': 'e2()',
    '[style.--radix-toast-swipe-end-x]': 'e2()',
    tabindex: '0',
    '[attr.data-tone]': 'e3()',
    '[attr.data-state]': 'e4()',
    '[attr.data-swipe]': 'e5()',
    'data-swipe-direction': 'right',
    'data-member': 'toast',
    '(keydown)': 'h1($event)',
    '(pointerdown)': 'h2($event)',
    '(pointermove)': 'h3($event)',
    '(pointerup)': 'h4()',
    '(pointercancel)': 'h5()',
  },
  providers: [...MEMBER_PROVIDERS],
  imports: [Render, Button, Icon],
  // prettier-ignore
  template: `@if (e6()) {<!-- wait -->
<span
[attr.class]="e7()"
aria-hidden="true"
><pm-icon
name="loading"
></pm-icon></span>} @else if (e8()) {<!-- tone -->
<span
[attr.class]="e9()"
><pm-icon
[name]="e10()"
></pm-icon></span>}
<!-- text -->
<div
[attr.class]="e11()"
><!-- title -->
<div
[attr.class]="e12()"
[attr.data-toast-title]="e13()"
>{{ e14() }}</div>
@if (e15()) {<!-- description -->
<div
[attr.class]="e16()"
>{{ e17() }}</div>}
@if (e18()) {<!-- content -->
<div
[attr.class]="e19()"
[attr.data-toast-content]="e20()"
>@if (template(e21())) {<ng-container [pmRender]="e21()" />} @else {{{ e21() }}}</div>}</div>
@if (e22()) {<!-- action -->
<div
[attr.class]="e23()"
><pm-button
variant="ghost"
[tone]="e24()"
size="sm"
[label]="e25()"
(click)="h6()"
></pm-button></div>}
@if (e26()) {<!-- close -->
<div
[attr.class]="e27()"
><pm-button
variant="ghost"
tone="neutral"
size="sm"
[iconOnly]="e28()"
icon="close"
[label]="e29()"
(click)="h7()"
></pm-button></div>}`,
})
export class ToastCard {
  readonly record = input.required<ToastCardProps['record']>()
  /**
   * The close button’s accessible name.
   */
  readonly dismissLabel = input.required<ToastCardProps['dismissLabel']>()
  /**
   * The reader is on the list, so the timer waits.
   */
  readonly paused = input.required<ToastCardProps['paused']>()
  protected readonly $ = useMember({
    element: 'pmToastCard',
    events: [],
    props: {
      record: () => this.record(),
      dismissLabel: () => this.dismissLabel(),
      paused: () => this.paused(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly swipe = cell(() => '')
  protected readonly tracking = cell(() => false)
  protected readonly startX = cell(() => 0)
  protected readonly deltaX = cell(() => 0)
  protected readonly card = elementRef<HTMLElement>()
  protected readonly icon = derived(() =>
    this.$p.record.tone === 'neutral' ? null : TOAST_TONE_ICON[this.$p.record.tone],
  )
  protected readonly clock = derived(() => toastClock())
  protected readonly dismissible = derived(() => this.$p.record.dismissible !== false)
  protected readonly dismiss = derived(() => (): void => {
    if (this.dismissible.value) toast.dismiss(this.$p.record.id)
  })
  protected readonly act = derived(() => (): void => {
    this.$p.record.action?.onClick()
    toast.dismiss(this.$p.record.id)
  })
  protected readonly press = derived(() => (event: PointerEvent): void => {
    if (
      !this.dismissible.value ||
      event.button !== 0 ||
      (event.target as Element).closest('button') !== null
    )
      return
    this.tracking.value = true
    this.startX.value = event.clientX
    this.deltaX.value = 0
  })
  protected readonly drag = derived(() => (event: PointerEvent): void => {
    if (!this.tracking.value) return
    this.deltaX.value = Math.max(0, event.clientX - this.startX.value)
    if (this.deltaX.value > 0) this.swipe.value = 'move'
  })
  protected readonly lift = derived(() => (): void => {
    if (!this.tracking.value) return
    this.tracking.value = false
    if (this.swipe.value !== 'move') return
    if (this.deltaX.value > 50) {
      this.swipe.value = 'end'
      this.dismiss.value()
    } else {
      this.swipe.value = 'cancel'
      this.deltaX.value = 0
    }
  })
  protected readonly present = setup(() =>
    usePresence(
      () => this.$p.record.closing !== true,
      () => this.card.value,
      'toast.enter',
    ),
  )
  protected readonly template = isTemplate
  private release3: (() => void) | undefined

  constructor() {
    hostRef(this.card)
    watchEffect(
      () => this.$p.record.closing,
      () => this.effect1(),
      false,
    )
    watchEffect(
      () => this.present.value(),
      () => this.effect2(),
      false,
    )
    inject(DestroyRef).onDestroy(() => this.release3?.())
    watchEffect(
      () => [this.$p.record.revision, this.$p.paused, this.$p.record.closing],
      () => this.effect3(),
      true,
    )
  }

  protected e1() {
    return styles.toast
  }

  protected e2() {
    return `${this.deltaX.value}px`
  }

  protected e3() {
    return this.$p.record.tone
  }

  protected e4() {
    return this.$p.record.closing === true ? 'closed' : 'open'
  }

  protected e5() {
    return this.swipe.value === '' ? undefined : this.swipe.value
  }

  protected h1($event: KeyboardEvent): void {
    if ($event.key === 'Escape' && !$event.defaultPrevented && !composingKey($event))
      void ($event.preventDefault(), this.dismiss.value())
  }

  protected h2($event: PointerEvent): void {
    this.press.value($event)
  }

  protected h3($event: PointerEvent): void {
    this.drag.value($event)
  }

  protected h4(): void {
    this.lift.value()
  }

  protected h5(): void {
    this.lift.value()
  }

  protected e6() {
    return this.$p.record.loading === true
  }

  protected e7() {
    if (!(this.$p.record.loading === true)) return undefined as never
    return classes(styles.tone, styles.wait)
  }

  protected e8() {
    if (this.$p.record.loading === true) return undefined as never
    return this.icon.value !== null
  }

  protected e9() {
    if (this.$p.record.loading === true) return undefined as never
    if (!(this.icon.value !== null)) return undefined as never
    return styles.tone
  }

  protected e10(): IconProps['name'] {
    if (this.$p.record.loading === true) return undefined as never
    if (!(this.icon.value !== null)) return undefined as never
    return this.icon.value
  }

  protected e11() {
    return styles.text
  }

  protected e12() {
    return styles.title
  }

  protected e13() {
    return ''
  }

  protected e14() {
    return this.$p.record.title
  }

  protected e15() {
    return this.$p.record.description !== undefined
  }

  protected e16() {
    if (!(this.$p.record.description !== undefined)) return undefined as never
    return styles.description
  }

  protected e17() {
    if (!(this.$p.record.description !== undefined)) return undefined as never
    return this.$p.record.description
  }

  protected e18() {
    return this.$p.record.content !== undefined
  }

  protected e19() {
    if (!(this.$p.record.content !== undefined)) return undefined as never
    return styles.content
  }

  protected e20() {
    if (!(this.$p.record.content !== undefined)) return undefined as never
    return ''
  }

  protected e21() {
    if (!(this.$p.record.content !== undefined)) return undefined as never
    return this.$p.record.content
  }

  protected e22() {
    return this.$p.record.action !== undefined
  }

  protected e23() {
    if (!(this.$p.record.action !== undefined)) return undefined as never
    return styles.action
  }

  protected e24(): ButtonProps['tone'] {
    if (!(this.$p.record.action !== undefined)) return undefined as never
    return this.$p.record.tone === 'danger' ? 'danger' : 'accent'
  }

  protected e25(): ButtonProps['label'] {
    if (!(this.$p.record.action !== undefined)) return undefined as never
    return this.$p.record.action?.label ?? ''
  }

  protected h6(): void {
    if (!(this.$p.record.action !== undefined)) return
    this.act.value()
  }

  protected e26() {
    return this.dismissible.value
  }

  protected e27() {
    if (!this.dismissible.value) return undefined as never
    return styles.close
  }

  protected e28(): ButtonProps['iconOnly'] {
    if (!this.dismissible.value) return undefined as never
    return true
  }

  protected e29(): ButtonProps['label'] {
    if (!this.dismissible.value) return undefined as never
    return this.$p.dismissLabel
  }

  protected h7(): void {
    if (!this.dismissible.value) return
    this.dismiss.value()
  }

  private effect1(): void {
    void (this.$p.record.closing === true && focusAfterToast(this.card.value))
  }

  private effect2(): void {
    void (this.present.value() || removeToast(this.$p.record.id, this.$p.record.raised))
  }

  private effect3(): void {
    this.release3?.()
    const timer = setTimeout(
      () => {
        void (
          !this.$p.paused &&
          this.$p.record.closing !== true &&
          this.dismissible.value &&
          Number.isFinite(this.$p.record.durationMs) &&
          toast.dismiss(this.$p.record.id)
        )
      },
      Number.isFinite(this.$p.record.durationMs)
        ? toastTimeLeft(
            this.clock.value,
            this.$p.record.revision,
            this.$p.record.durationMs,
            !this.$p.paused && this.$p.record.closing !== true,
          )
        : 0,
    )
    this.release3 = () => clearTimeout(timer)
  }
}
